        for (Map.Entry<String, List<Resource>> entry : mReferences.entrySet()) {
            List<Resource> references = entry.getValue();
            if (references.size() > 1) {
                Resource first = references.get(0);
                for (int i = 1; i < references.size(); i++) {
                    Resource duplicate = references.get(i);
                    String message = String.format(
